const fn = new Function(code + "\nreturn { attempt };");
const { attempt } = fn();
const a = attempt(() => [1, 2, 3]);
if (a.ok !== true || a.value.join() !== "1,2,3") throw new Error("Arrays pass through inside ok.");
const b = attempt(() => ({ deep: { x: 1 } }));
if (b.value.deep.x !== 1) throw new Error("Objects pass through.");
const c = attempt(() => { throw new Error("nope"); });
if (c.ok !== false || c.error !== "nope") throw new Error("Failures become { ok: false, error }.");
